// Stage 5 synthetic live-TV fixtures for on-TV measurements (dev-sink only; never part of the app).
// Synthetic streams generated by ffmpeg with the probe 2 encoder settings (probe2/server/make-media.mjs,
// imported read-only). Serves:
//   /live/<variant>.ts                 continuous MPEG-TS (h264_aac, h264_mp2, h264_ac3, hevc_aac), one
//                                      ffmpeg per variant shared by all clients
//   /fixture/live.m3u                  4 test channels: 2 working, 1 HTTP 404, 1 connection refused
//   /fixture/channels.m3u?n=N          N channels in 100 groups, all pointing at /live/h264_aac.ts
//   /fixture/guide.xml?n=K             XMLTV for ids ch0…chK-1, 26 one-hour programmes around now
import { spawn } from 'node:child_process';
import { gzipSync } from 'node:zlib';
import { LIVE, LIVE_SRC } from '../../probe2/server/make-media.mjs';

const broadcasters = new Map();

function broadcaster(variant) {
  if (broadcasters.has(variant)) return broadcasters.get(variant);
  const clients = new Set();
  const ff = spawn('ffmpeg', ['-hide_banner', '-loglevel', 'error', ...LIVE_SRC, ...LIVE[variant], '-f', 'mpegts', 'pipe:1'], { stdio: ['ignore', 'pipe', 'inherit'] });
  // Clients join a running stream. By default they get the bytes from wherever the stream is
  // (usually inside a 188-byte TS packet). Clients marked `aligned` (?align=1) receive whole packets
  // only and start at a PAT packet (PID 0), as a packet-aware restreamer would send them (Stage 5.1).
  let rem = Buffer.alloc(0);
  ff.stdout.on('data', (buf) => {
    const all = rem.length ? Buffer.concat([rem, buf]) : buf;
    const whole = all.length - (all.length % 188);
    const packets = all.subarray(0, whole);
    rem = Buffer.from(all.subarray(whole));
    for (const res of clients) {
      if (!res.aligned) { res.write(buf); continue; }
      if (!res.started) {
        let i = 0;
        while (i < packets.length && !(packets[i] === 0x47 && (((packets[i + 1] & 0x1f) << 8) | packets[i + 2]) === 0)) i += 188;
        if (i >= packets.length) continue;
        res.started = true;
        res.write(packets.subarray(i));
      } else if (packets.length) {
        res.write(packets);
      }
    }
  });
  ff.on('exit', () => { broadcasters.delete(variant); for (const res of clients) res.end(); });
  const b = { clients, ff };
  broadcasters.set(variant, b);
  return b;
}

export function stopBroadcasters() {
  for (const b of broadcasters.values()) b.ff.kill();
}

function q(url) {
  const out = {};
  const i = url.indexOf('?');
  if (i < 0) return out;
  for (const p of url.substring(i + 1).split('&')) {
    const e = p.indexOf('=');
    if (e > 0) out[p.substring(0, e)] = decodeURIComponent(p.substring(e + 1));
  }
  return out;
}

function xmltvTime(ms) {
  return new Date(ms).toISOString().replace(/[-:T]/g, '').substring(0, 14) + ' +0000';
}

export function handleLiveFixture(req, res, origin) {
  const url = req.url || '';
  const path = url.split('?')[0];
  const head = { 'Access-Control-Allow-Origin': '*', 'Cache-Control': 'no-store' };
  const live = /^\/live\/([a-z0-9_]+)\.ts$/.exec(path);
  if (live) {
    if (!LIVE[live[1]]) { res.writeHead(404, head); res.end(); return true; }
    res.writeHead(200, { ...head, 'Content-Type': 'video/mp2t' });
    const b = broadcaster(live[1]);
    const t0 = Date.now();
    const w = res.write.bind(res);
    let bytes = 0;
    res.write = (buf) => { bytes += buf.length; return w(buf); };
    res.aligned = /[?&]align=1/.test(url);
    b.clients.add(res);
    console.log('[live] ' + new Date(t0).toISOString() + ' open ' + live[1] + (res.aligned ? ' aligned' : '') + ' clients=' + b.clients.size);
    req.on('close', () => {
      b.clients.delete(res);
      console.log('[live] ' + new Date().toISOString() + ' close ' + live[1] + ' after ' + (Date.now() - t0) + ' ms, ' + bytes + ' bytes, clients=' + b.clients.size);
    });
    return true;
  }
  if (path.indexOf('/live/') === 0 || path === '/fixture/live.m3u') console.log('[live] ' + new Date().toISOString() + ' ' + req.method + ' ' + path);
  if (path === '/fixture/live.m3u') {
    const host = origin.replace(/:\d+$/, '');
    const al = q(url).align === '1' ? '?align=1' : '';
    res.writeHead(200, { ...head, 'Content-Type': 'audio/x-mpegurl' });
    res.end('#EXTM3U url-tvg="' + origin + '/fixture/guide.xml?n=4"\n' +
      '#EXTINF:-1 tvg-id="ch0" tvg-chno="1" group-title="Test",Test H.264 AAC\n' + origin + '/live/h264_aac.ts' + al + '\n' +
      '#EXTINF:-1 tvg-id="ch1" tvg-chno="2" group-title="Test",Test H.264 MP2\n' + origin + '/live/h264_mp2.ts' + al + '\n' +
      '#EXTINF:-1 tvg-id="ch2" tvg-chno="3" group-title="Test",Dead channel (404)\n' + origin + '/live/missing.ts\n' +
      '#EXTINF:-1 tvg-id="ch3" tvg-chno="4" group-title="Test",Refused channel\n' + host + ':8096/live/x.ts\n');
    return true;
  }
  if (path === '/fixture/channels.m3u') {
    const n = Math.max(1, Math.min(300000, Number(q(url).n) || 1000));
    res.writeHead(200, { ...head, 'Content-Type': 'audio/x-mpegurl' });
    // ?guide=<path> replaces the default guide (Stage 5.1 gzip variants), e.g. guide=/fixture/guide.xml.gz?n=2000
    const guide = q(url).guide ? origin + q(url).guide : origin + '/fixture/guide.xml?n=' + Math.min(n, 2000);
    const parts = ['#EXTM3U url-tvg="' + guide + '"\n'];
    for (let i = 0; i < n; i++) {
      parts.push('#EXTINF:-1 tvg-id="ch' + i + '" tvg-logo="' + origin + '/logos/' + (i % 500) + '.png" group-title="Group ' + (i % 100) + '",Channel ' + i + '\n' + origin + '/live/h264_aac.ts?c=' + i + '\n');
    }
    res.end(parts.join(''));
    return true;
  }
  // Stage 5.1 gzip variants of the guide:
  //   /fixture/guide.xml.gz          gzip, Content-Type application/gzip
  //   /fixture/guide-gz              gzip without a .gz name, Content-Type application/octet-stream
  //   /fixture/guide-ce.xml.gz       gzip sent with Content-Encoding: gzip (the browser decodes it)
  //   /fixture/guide-corrupt.xml.gz  64 bytes damaged in the middle
  //   /fixture/guide-trunc.xml.gz    the last 30 % missing
  const gzv = /^\/fixture\/(guide\.xml\.gz|guide-gz|guide-ce\.xml\.gz|guide-corrupt\.xml\.gz|guide-trunc\.xml\.gz)$/.exec(path);
  if (path === '/fixture/guide.xml' || gzv) {
    const n = Math.max(1, Math.min(10000, Number(q(url).n) || 4));
    const base = Math.floor(Date.now() / 3600000) * 3600000;
    if (!gzv) res.writeHead(200, { ...head, 'Content-Type': 'application/xml; charset=utf-8' });
    const parts = ['<?xml version="1.0" encoding="UTF-8"?>\n<tv generator-info-name="screenshelf-tv-fixture">\n'];
    for (let c = 0; c < n; c++) parts.push('<channel id="ch' + c + '"><display-name>Channel ' + c + '</display-name></channel>\n');
    for (let c = 0; c < n; c++) {
      for (let k = 0; k < 26; k++) {
        const s = base + (k - 2) * 3600000;
        parts.push('<programme start="' + xmltvTime(s) + '" stop="' + xmltvTime(s + 3600000) + '" channel="ch' + c + '"><title>Programme ' + k + ' on channel ' + c +
          '</title><desc>Synthetic description for programme ' + k + ' &amp; channel ' + c + '.</desc></programme>\n');
      }
    }
    parts.push('</tv>\n');
    if (!gzv) { res.end(parts.join('')); return true; }
    let body = gzipSync(Buffer.from(parts.join('')), { level: 6 });
    const v = gzv[1];
    if (v.indexOf('corrupt') >= 0) { body = Buffer.from(body); for (let i = 0; i < 64; i++) body[(body.length >> 1) + i] ^= 0xa5; }
    if (v.indexOf('trunc') >= 0) body = body.subarray(0, Math.floor(body.length * 0.7));
    const h2 = { ...head, 'Content-Type': v === 'guide-gz' ? 'application/octet-stream' : (v === 'guide-ce.xml.gz' ? 'application/xml' : 'application/gzip'), 'Content-Length': String(body.length) };
    if (v === 'guide-ce.xml.gz') h2['Content-Encoding'] = 'gzip';
    console.log('[guide] ' + new Date().toISOString() + ' ' + v + ' n=' + n + ' ' + body.length + ' bytes gzip');
    res.writeHead(200, h2);
    res.end(body);
    return true;
  }
  return false;
}
